import os, json, time
from bioblend.galaxy import GalaxyInstance

with open(os.environ.get('GALAXY_API_KEY_FILE', '')) as f:
    api_key = f.read().strip()

gi = GalaxyInstance(url='https://usegalaxy.org', key=api_key)
history_id = "bbd44e69cb8906b5bae20868a11cf98f"

tool_id = "toolshed.g2.bx.psu.edu/repos/iuc/deseq2/deseq2/2.11.40.8+galaxy3"

inputs = {
    "select_data": {
        "how": "sample_sheet_contrasts",
        "countsFile": {"src": "hdca", "id": "70ef517a6ff687f2"},
        "sample_sheet": {"src": "hda", "id": "f9cad7b01a4721353c4c466002dfb34a"},
        "design_formula_mode": {
            "mode": "automatic",
            "factor": [3, 2],
            "reference_level": "Control",
            "target_level": "ASXL1"
        }
    },
    "header": True,
    "tximport": {
        "tximport_selector": "count"
    },
    "advanced_options": {
        "lfc_shrinkage_type": "apeglm",
        "fit_type": "1"
    },
    "output_options": {
        "alpha_ma": 0.05
    }
}

print("Submitting DESeq2 job...")
result = gi.tools.run_tool(
    history_id=history_id,
    tool_id=tool_id,
    tool_inputs=inputs,
    input_format="21.01"
)

outputs = result.get('outputs', [])
output_ids = [o['id'] for o in outputs]
print(f"Job submitted. Output IDs: {output_ids}")
print(f"Output names: {[o['name'] for o in outputs]}")

# Wait for completion
print("Waiting for completion...")
for i in range(120):
    time.sleep(5)
    all_done = True
    for oid in output_ids:
        ds = gi.datasets.show_dataset(oid)
        state = ds['state']
        if state in ('new', 'queued', 'running'):
            all_done = False
            print(f"  {oid}: {state}")
    if all_done:
        break

print("\nFinal status:")
for oid in output_ids:
    ds = gi.datasets.show_dataset(oid)
    print(f"  {oid}: state={ds['state']}, size={ds.get('file_size', 0)}, name={ds.get('name', '')}")
    if ds['state'] == 'error':
        job = gi.jobs.show_job(ds.get('creating_job'), full_details=True)
        stderr = job.get('stderr', '')
        if stderr:
            print(f"    Stderr: {stderr[:500]}")
        stdout = job.get('stdout', '')
        if stdout:
            print(f"    Stdout: {stdout[:500]}")
