        if state in ('new', 'queued', 'running'):
            all_done = False
            if i % 6 == 0:
                print(f"  Still running ({i*5}s)...")
    if all_done:
        break

print("\nFinal status:")
for oid in output_ids:
    ds = gi.datasets.show_dataset(oid)
    print(f"  {oid}: state={ds['state']}, size={ds.get('file_size', 0)}")
    if ds['state'] == 'error':
        job = gi.jobs.show_job(ds.get('creating_job'), full_details=True)
