        if stderr:
            print(f"    Stderr: {stderr[:500]}")
        if stdout:
            print(f"    Stdout: {stdout[:500]}")
    elif ds['state'] == 'ok':
        # Peak at first few lines
        print(f"    Name: {ds['name']}")
